'use strict';

// Routed Gothic (SIL OFL 1.1) - https://github.com/dse/routed-gothic
// Base64-embedded (see fonts/*.ttf, fonts/LICENSE-routed-gothic.md) so
// fiziko's labels stay legible without the viewer having this font
// installed, and so an exported SVG (Save SVG/Preview SVG) stays fully
// self-contained rather than depending on an external font file.
const ROUTED_GOTHIC_BASE64 = '';

// Narrow, half-italic variant - used for linkage/anomer labels, matching
// the conventional italic styling of anomeric configuration annotations
// in glycan diagrams.
const ROUTED_GOTHIC_NARROW_HALF_ITALIC_BASE64 = '';

export default ROUTED_GOTHIC_BASE64;
export { ROUTED_GOTHIC_NARROW_HALF_ITALIC_BASE64 };
